{
  "name": "@caveman-ai/cli",
  "version": "1.2.0",
  "description": "Caveman CLI — wrap coding agents with recoverable local context compression and truthful metering (`caveman claude`), then drive Caveman Cloud from terminal. Compression and metering run in companion Go binaries: run `caveman setup` to see install state. Local savings stay inferred until verified.",
  "license": "MIT",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/JuliusBrussee/caveman.git",
    "directory": "packages/cli"
  },
  "homepage": "https://getcaveman.dev",
  "bugs": {
    "url": "https://github.com/JuliusBrussee/caveman/issues"
  },
  "engines": {
    "node": ">=22.13"
  },
  "bin": {
    "caveman": "dist/index.js",
    "cave": "dist/index.js"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "node scripts/gen-binaries.mjs && node scripts/gen-wedge-installer.mjs && node scripts/compile-registries.mjs && tsc && node scripts/bundle-delegate.mjs && node scripts/bundle-tui.mjs && node scripts/shebang.mjs",
    "prepack": "npm run build",
    "lint": "tsc --noEmit",
    "test": "node scripts/gen-binaries.mjs && node scripts/gen-wedge-installer.mjs && node scripts/compile-registries.mjs && tsc && node scripts/bundle-delegate.mjs && node scripts/bundle-tui.mjs && node scripts/shebang.mjs && node --test --test-concurrency=4 tests/*.runtime.mjs",
    "bench:native": "node scripts/benchmark-native-hooks.mjs",
    "test:fast": "node scripts/gen-binaries.mjs && node scripts/gen-wedge-installer.mjs && node scripts/compile-registries.mjs && tsc && node scripts/bundle-delegate.mjs && node scripts/bundle-tui.mjs && node --test --test-concurrency=4 --test-reporter=dot tests/agent-native.runtime.mjs tests/billing.runtime.mjs tests/capability-config.runtime.mjs tests/login.runtime.mjs tests/mcp-surface.runtime.mjs tests/porcelain.runtime.mjs tests/practice-registry.runtime.mjs tests/skills.runtime.mjs tests/status.runtime.mjs tests/subscription-recovery.runtime.mjs tests/wrap-gate.runtime.mjs"
  },
  "dependencies": {},
  "devDependencies": {
    "@clack/prompts": "1.7.0",
    "@types/node": "24.10.1",
    "esbuild": "0.28.1",
    "typescript": "5.9.3"
  }
}

import { spawn, spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdtempSync, mkdirSync, rmSync } from "node:fs";
import { createServer } from "node:net";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const hook = join(root, "dist", "native-hook-fast.js");
const home = mkdtempSync(join(process.env.CAVEMAN_BENCH_TMPDIR ?? tmpdir(), "caveman-native-bench-"));
let nativeHookBin = process.env.CAVEMAN_NATIVE_HOOK_BIN ?? process.env.CAVEMAN_PROXY_BIN;
if (!nativeHookBin) {
  const candidate = join(home, process.platform === "win32" ? "caveman-proxy.exe" : "caveman-proxy");
  const build = spawnSync("go", ["build", "-o", candidate, "./proxy/cmd/caveman-proxy"], {
    cwd: join(root, ".."),
    env: process.env,
    encoding: "utf8",
  });
  if (build.status === 0) nativeHookBin = candidate;
  else process.stderr.write(`native hook benchmark: Go bridge build unavailable; measuring Node fallback (${build.stderr.trim()})\n`);
}
const runDir = join(home, "run");
const socketPath = process.platform === "win32"
  ? `\\\\.\\pipe\\caveman-native-${createHash("sha256").update(resolve(home).replaceAll("/", "\\").toLowerCase()).digest("hex").slice(0, 16)}`
  : join(runDir, "native.sock");
mkdirSync(runDir, { recursive: true, mode: 0o700 });

const runtime = createServer((socket) => {
  let raw = "";
  let answered = false;
  socket.setEncoding("utf8");
  socket.on("error", () => {});
  socket.on("data", (chunk) => {
    raw += chunk;
    if (answered || !raw.includes("\n")) return;
    answered = true;
    let event = "unknown";
    try { event = JSON.parse(raw).event.type; } catch { /* hook owns fail-open behavior */ }
    socket.end(`${JSON.stringify({
      protocol_version: 1,
      action: "allow",
      decision_id: `bench-${event}`,
      visibility: "silent",
      fail_open: true,
    })}\n`);
  });
});
const route = createServer((socket) => socket.end());

function listen(server, ...args) {
  return new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(...args, resolve);
  });
}

function close(server) {
  return new Promise((resolve) => server.close(resolve));
}

function runHook(payload, env) {
  const started = process.hrtime.bigint();
  return new Promise((resolve, reject) => {
    const child = nativeHookBin
      ? spawn(nativeHookBin, ["native-hook", "claude", "--adapter", hook], { env })
      : spawn(process.execPath, [hook, "native-hook", "claude"], { env });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (chunk) => (stdout += chunk));
    child.stderr.on("data", (chunk) => (stderr += chunk));
    child.on("error", reject);
    child.on("exit", (code) => resolve({
      code,
      stdout,
      stderr,
      ms: Number(process.hrtime.bigint() - started) / 1e6,
    }));
    child.stdin.end(JSON.stringify(payload));
  });
}

function p95(values) {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.max(0, Math.ceil(sorted.length * 0.95) - 1)];
}

const requested = Number.parseInt(process.env.CAVEMAN_BENCH_SAMPLES ?? "30", 10);
const samples = Number.isFinite(requested) ? Math.min(200, Math.max(10, requested)) : 30;
const warmups = 5;

try {
  await listen(runtime, socketPath);
  await listen(route, 0, "127.0.0.1");
  const address = route.address();
  if (!address || typeof address === "string") throw new Error("route benchmark listener has no TCP address");
  const env = {
    ...process.env,
    HOME: home,
    CAVEMAN_HOME: home,
    CAVEMAN_NATIVE_MODE: "safe",
    CAVEMAN_TELEMETRY: "0",
    CAVE_GATEWAY_URL: `http://127.0.0.1:${address.port}`,
  };
  const noOpPayload = {
    hook_event_name: "PreToolUse",
    session_id: "bench-hot",
    tool_name: "unknown_tool",
    tool_input: {},
  };
  const startupPayload = { hook_event_name: "SessionStart", session_id: "bench-startup" };
  for (let i = 0; i < warmups; i += 1) {
    const result = await runHook(noOpPayload, env);
    if (result.code !== 0) throw new Error(`warmup failed: ${result.stderr}`);
  }
  const noOp = [];
  for (let i = 0; i < samples; i += 1) {
    const result = await runHook(noOpPayload, env);
    if (result.code !== 0 || result.stdout !== "" || result.stderr !== "") {
      throw new Error(`no-op hook emitted intervention: code=${result.code} stdout=${JSON.stringify(result.stdout)} stderr=${JSON.stringify(result.stderr)}`);
    }
    noOp.push(result.ms);
  }
  const startup = [];
  for (let i = 0; i < samples; i += 1) {
    const result = await runHook({ ...startupPayload, session_id: `bench-startup-${i}` }, env);
    if (result.code !== 0 || !result.stdout.includes("smallest coherent change") || result.stderr !== "") {
      throw new Error(`startup hook failed: code=${result.code} stdout=${JSON.stringify(result.stdout)} stderr=${JSON.stringify(result.stderr)}`);
    }
    startup.push(result.ms);
  }
  const noOpP95 = p95(noOp);
  const startupP95 = p95(startup);
  const report = {
    schema: "caveman.native-hook-benchmark.v1",
    basis: "local_engineering_measurement_not_product_savings_evidence",
    adapter: nativeHookBin ? "caveman-proxy-native-bridge" : "node-fast-adapter-fallback",
    samples,
    warmups,
    no_op_hot_path: { p95_ms: Number(noOpP95.toFixed(3)), target_ms: 50, passed: noOpP95 < 50 },
    warm_session_startup: { p95_ms: Number(startupP95.toFixed(3)), target_ms: 300, passed: startupP95 < 300 },
    hard_pre_tool_timeout_ms: 250,
  };
  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
  if (process.argv.includes("--enforce") && (!report.no_op_hot_path.passed || !report.warm_session_startup.passed)) process.exitCode = 1;
} finally {
  await close(runtime);
  await close(route);
  rmSync(home, { recursive: true, force: true });
}

import { chmodSync, copyFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const packageRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const roots = [
  resolve(packageRoot, ".."),
  resolve(packageRoot, "..", ".."),
];
const source = roots
  .flatMap((root) => [
    join(root, "agents", "delegate", "caveman-delegate-mcp.mjs"),
    join(root, "public", "agents", "delegate", "caveman-delegate-mcp.mjs"),
  ])
  .find((candidate) => existsSync(candidate));

if (!source) {
  console.error("delegate bundle failed: canonical public/agents/delegate/caveman-delegate-mcp.mjs not found");
  process.exit(1);
}

const target = join(packageRoot, "dist", "caveman-delegate-mcp.mjs");
const helperSource = join(dirname(source), "portable-process.mjs");
const helperTarget = join(packageRoot, "dist", "portable-process.mjs");
if (!existsSync(helperSource)) {
  console.error("delegate bundle failed: portable-process.mjs not found beside canonical delegate");
  process.exit(1);
}
mkdirSync(dirname(target), { recursive: true });
copyFileSync(source, target);
copyFileSync(helperSource, helperTarget);
chmodSync(target, 0o755);

import { build } from "esbuild";
import { fileURLToPath } from "node:url";

const entry = fileURLToPath(new URL("../src/learn-tui.ts", import.meta.url));
const outfile = fileURLToPath(new URL("../dist/learn-tui.js", import.meta.url));

await build({
  entryPoints: [entry],
  outfile,
  bundle: true,
  platform: "node",
  format: "esm",
  target: "node22",
  minify: true,
  legalComments: "eof",
  sourcemap: false,
  banner: {
    js: "// Bundled interactive UI. @clack/prompts remains a build-time dependency only.",
  },
});

import { existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";

const packageRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const candidates = [
  resolve(packageRoot, ".."),
  resolve(packageRoot, "..", ".."),
];
const registryRoot = candidates.find((candidate) =>
  existsSync(join(candidate, "agents", "compile.mjs"))
  && existsSync(join(candidate, "integrations", "compile.mjs"))
  && existsSync(join(candidate, "skills", "compile.mjs")));

if (!registryRoot) {
  console.error("registry compile failed: agents/, integrations/, and skills/ must share a parent with the CLI package");
  process.exit(1);
}

for (const registry of ["agents", "integrations", "skills"]) {
  const result = spawnSync(
    process.execPath,
    [join(registryRoot, registry, "compile.mjs")],
    {
      cwd: registryRoot,
      env: { ...process.env, CAVEMAN_CLI_DIR: packageRoot },
      stdio: "inherit",
    },
  );
  if (result.error) {
    console.error(`registry compile failed: ${result.error.message}`);
    process.exit(1);
  }
  if (result.status !== 0) process.exit(result.status ?? 1);
}

#!/usr/bin/env node
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const release = readFileSync(join(root, "BINARY_RELEASE"), "utf8").trim();
const publicKey = readFileSync(join(root, "BINARY_SIGNING_PUBKEY.pub"), "utf8");
const output = join(root, "src", "binaries.generated.ts");
const releaseBase = "https://github.com/JuliusBrussee/caveman/releases/download";

if (!/^bin-v\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?$/.test(release)) {
  throw new Error(`BINARY_RELEASE must be a bin-v semver tag, got ${JSON.stringify(release)}`);
}
if (!/^-----BEGIN PUBLIC KEY-----\n[\s\S]+\n-----END PUBLIC KEY-----\n$/.test(publicKey)) {
  throw new Error("BINARY_SIGNING_PUBKEY.pub must contain one newline-terminated PEM public key");
}

const generated = `// Generated by scripts/gen-binaries.mjs. Do not edit.
export const BINARY_RELEASE = ${JSON.stringify(release)};
export const BINARY_RELEASE_BASE_DEFAULT = ${JSON.stringify(releaseBase)};
export const BINARY_SIGNING_PUBKEY = ${JSON.stringify(publicKey)};
`;

if (process.argv.includes("--check")) {
  if (readFileSync(output, "utf8") !== generated) {
    console.error("binary release constants are stale; run node packages/cli/scripts/gen-binaries.mjs");
    process.exit(1);
  }
} else {
  writeFileSync(output, generated);
  console.log(`generated binary release constants for ${release}`);
}

#!/usr/bin/env node
import { copyFileSync, existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const cli = join(dirname(fileURLToPath(import.meta.url)), "..");
const publicRoot = join(cli, "..");
const stackRoot = existsSync(join(publicRoot, "mcp")) ? publicRoot : join(publicRoot, "..");
const release = readFileSync(join(cli, "BINARY_RELEASE"), "utf8").trim();
const publicKey = readFileSync(join(cli, "BINARY_SIGNING_PUBKEY.pub"), "utf8");
const releaseBase = "https://github.com/JuliusBrussee/caveman/releases/download";
const source = join(publicRoot, "shared", "binary-installer", "installer.mjs");
const generated = `// Generated by packages/cli/scripts/gen-wedge-installer.mjs. Do not edit.
export const BINARY_RELEASE = ${JSON.stringify(release)};
export const BINARY_RELEASE_BASE_DEFAULT = ${JSON.stringify(releaseBase)};
export const BINARY_SIGNING_PUBKEY = ${JSON.stringify(publicKey)};
`;

for (const target of [
  join(publicRoot, "shared", "binary-installer"),
  join(stackRoot, "mcp", "bin"),
  join(stackRoot, "shrink", "bin"),
  join(stackRoot, "browse", "bin"),
]) {
  if (!existsSync(target)) continue;
  writeFileSync(join(target, "release.generated.mjs"), generated);
  if (target !== join(publicRoot, "shared", "binary-installer")) {
    copyFileSync(source, join(target, "binary-installer.generated.mjs"));
  }
}
console.log(`generated standalone wedge installers for ${release}`);

import { chmod, readFile, writeFile } from "node:fs/promises";

const file = new URL("../dist/index.js", import.meta.url);
const body = await readFile(file, "utf8");
if (!body.startsWith("#!/usr/bin/env node")) {
  await writeFile(file, `#!/usr/bin/env node\n${body}`);
}
await chmod(file, 0o755);

import { createInterface } from "node:readline";
import type { Readable, Writable } from "node:stream";

export type JSONValue =
  | null
  | boolean
  | number
  | string
  | JSONValue[]
  | { [key: string]: JSONValue };

export type JSONObject = { [key: string]: JSONValue };

export type AgentMcpClient = {
  request(path: string, options?: { method?: "GET" | "POST"; body?: JSONObject }): Promise<JSONValue>;
  projectId(): Promise<string>;
  recordToolCall?(event: { tool: string; result: "ok" | "error"; durationMs: number }): void;
};

type ToolDefinition = {
  name: string;
  description: string;
  inputSchema: JSONObject;
  outputSchema: JSONObject;
  annotations: {
    title: string;
    readOnlyHint: boolean;
    destructiveHint: boolean;
    idempotentHint: boolean;
    openWorldHint: boolean;
  };
};

type ToolResult = {
  content: Array<{ type: "text"; text: string }>;
  structuredContent: JSONObject;
  isError?: boolean;
};

type McpSessionState = {
  negotiated: boolean;
  initialized: boolean;
};

const LATEST_PROTOCOL_VERSION = "2025-11-25";
const SUPPORTED_PROTOCOL_VERSIONS = new Set([
  "2024-11-05",
  "2025-03-26",
  "2025-06-18",
  LATEST_PROTOCOL_VERSION,
]);

const OBJECT_OUTPUT: JSONObject = {
  type: "object",
  additionalProperties: true,
};

